/**
 * Samtal på distans (0.29, Kommunikation & samspel → Samtal på distans, modules 1151–1157): phone calls,
 * video calls, voice messages, sms and chat, group conversations, misunderstandings in text and netiquette.
 * Phones, laptops and chat screens carry icons, digits and punctuation, never the word itself. Abstract words
 * get a small scene with a grey reference or a before/after arrow so that the property dominates the picture.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { HL, arm, bubble, cloud, dog, globe, heart, thought } from './people';
import { P, greyed } from './blindFix';
import { fc } from './emotions';

const f1 = (n: number) => +n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
const T = (x: number, y: number, s: string, size = 12, col: string = C.ink, w = 800) => `<text x="${x}" y="${y}" font-family="system-ui,sans-serif" font-weight="${w}" font-size="${size}" text-anchor="middle" fill="${col}">${s}</text>`;
const dash = (d: string, col: string = HL, w = 1.6, da = '3 3') => `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-dasharray="${da}" stroke-linecap="round"/>`;
const RED = '#e8302c';
const GOOD = '#3a9a5a';
const BLUE = '#3a6ab0';
const SCR = '#eaf4fb';
const ME = '#c8e0f8';
const YOU = '#e2e6ea';

// ── Devices ─────────────────────────────────────────────────────────────────
/** Smartphone, centred; the screen spans x −11.4…11.4, y −19…18 in local units. */
const mob = (x: number, y: number, s = 1, inner: Svg = '', rot = 0) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, rect(-14, -24, 28, 48, C.dark, 4, C.ink, 1.6), rect(-11.4, -19, 22.8, 37, SCR, 1.4, null), circle(0, 21, 1.3, C.grey, null), inner);
/** Laptop standing on y; the screen spans x −26…26, y −36…−4 in local units. */
const laptop = (x: number, y: number, s = 1, inner: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-30, -40, 60, 40, C.dark, 3, C.ink, 1.8), rect(-26, -36, 52, 32, SCR, 1, null), inner, path('M-36 0 L36 0 L40 6 L-40 6 Z', '#9aa3ad', C.ink, 1.6));
/** Small phone held to the ear of a standing figure at x (height factor h). */
const earPhone = (x: number, h = 1, side: 1 | -1 = 1) => {
  const s = 0.84 * h, hy = 112 - 105 * s;
  return all(arm(f1(x + side * 12 * s), f1(112 - 84 * s), f1(x + side * 11 * s), f1(hy + 5 * s)), g(`translate(${f1(x + side * 10.5 * s)} ${f1(hy)}) rotate(${side * 14}) scale(${f1(s)})`, rect(-4, -8, 8, 16, C.dark, 2, C.ink, 1.2)));
};
/** Phone held in front of the chest of a standing figure. */
const handPhone = (x: number, h = 1, side: 1 | -1 = 1, inner: Svg = '') => {
  const s = 0.84 * h;
  return all(arm(f1(x + side * 12 * s), f1(112 - 84 * s), f1(x + side * 9 * s), f1(112 - 64 * s)), mob(f1(x + side * 9 * s), f1(112 - 70 * s), f1(0.42 * h), inner));
};
const handset = (x: number, y: number, s = 1, col: string = GOOD, rot = 0) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, path('M-6 -6 C-8 0 0 8 6 6 L6 2 L2 0 L0 2 C-2 0 -3 -1 -4 -3 L-2 -5 L-4 -8 Z', col, C.ink, 0.8));
const callBtn = (x: number, y: number, r: number, ok = true) => all(circle(x, y, r, ok ? GOOD : RED, C.ink, 1), g(`translate(${x} ${y}) rotate(${ok ? 0 : 135}) scale(${f1(r / 9)})`, handset(0, 0, 1, C.white)));

// ── Marks and icons ─────────────────────────────────────────────────────────
/** Sound arcs to one side of (x, y). */
const sound = (x: number, y: number, side: 1 | -1 = 1, n = 3, col: string = HL, step = 5) => all(...Array.from({ length: n }, (_, i) => { const r = 4 + i * step, x0 = x + side * i * 2.6; return line(`M${f1(x0)} ${f1(y - r)} Q${f1(x0 + side * r * 0.9)} ${y} ${f1(x0)} ${f1(y + r)}`, col, 1.6); }));
/** Ring marks around the top of a phone. */
const ring = (x: number, y: number, w = 16, col: string = HL) => all(line(`M${f1(x - w)} ${f1(y - 4)} l-5 -4 M${f1(x - w - 1)} ${f1(y + 4)} l-6 0 M${f1(x + w)} ${f1(y - 4)} l5 -4 M${f1(x + w + 1)} ${f1(y + 4)} l6 0`, col, 2));
const shake = (x: number, y: number, w = 16, h = 20, col: string = HL) => all(...[-1, 1].map((sd) => line(`M${f1(x + sd * w)} ${f1(y - h)} l${sd * 4} 5 l${-sd * 4} 5 l${sd * 4} 5 l${-sd * 4} 5 l${sd * 4} 5 l${-sd * 4} 5 l${sd * 4} 5 l${-sd * 4} 5`, col, 1.8)));
const mic = (x: number, y: number, s = 1, col: string = C.dark) => g(`translate(${x} ${y}) scale(${s})`, rect(-4, -10, 8, 13, col, 4, C.ink, 1.2), path('M-7 -1 C-7 8 7 8 7 -1', 'none', C.ink, 1.4), line('M0 6 L0 10 M-4 10 L4 10', C.ink, 1.4));
const camIcon = (x: number, y: number, s = 1, col: string = C.dark) => g(`translate(${x} ${y}) scale(${s})`, rect(-9, -6, 13, 12, col, 2, C.ink, 1.2), path('M4 -2 L10 -6 L10 6 L4 2 Z', col, C.ink, 1.2));
const slash = (x: number, y: number, r = 9) => all(line(`M${f1(x - r)} ${f1(y - r)} L${f1(x + r)} ${f1(y + r)}`, C.white, 4), line(`M${f1(x - r)} ${f1(y - r)} L${f1(x + r)} ${f1(y + r)}`, RED, 2.4));
const ban = (x: number, y: number, r = 12) => all(circle(x, y, r, 'none', RED, r * 0.18), line(`M${f1(x - r * 0.7)} ${f1(y - r * 0.7)} L${f1(x + r * 0.7)} ${f1(y + r * 0.7)}`, RED, r * 0.18));
const speakerIcon = (x: number, y: number, s = 1, col: string = C.dark) => g(`translate(${x} ${y}) scale(${s})`, path('M-8 -3 L-4 -3 L2 -8 L2 8 L-4 3 L-8 3 Z', col, C.ink, 1.1));
const bell = (x: number, y: number, s = 1, col: string = C.gold) => g(`translate(${x} ${y}) scale(${s})`, path('M-7 4 C-7 -2 -6 -8 0 -8 C6 -8 7 -2 7 4 L9 6 L-9 6 Z', col, C.ink, 1.2), circle(0, 8, 2, col, C.ink, 1));
const wifi = (x: number, y: number, s = 1, col: string = GOOD, n = 3, dim: string = C.grey2) => g(`translate(${x} ${y}) scale(${s})`, circle(0, 0, 2.2, n > 0 ? col : dim, null), ...[1, 2, 3].map((i) => path(`M${-i * 5} ${-i * 4} Q0 ${-i * 9} ${i * 5} ${-i * 4}`, 'none', i <= n ? col : dim, 2.6)));
const check = (x: number, y: number, s = 1, col: string = GOOD) => g(`translate(${x} ${y}) scale(${s})`, path('M-5 0 L-1.6 3.4 L5 -4', 'none', col, 2));
const okC = (x: number, y: number, r = 7) => all(circle(x, y, r, GOOD, C.ink, 1.2), path(`M${f1(x - r * 0.45)} ${y} L${f1(x - r * 0.1)} ${f1(y + r * 0.35)} L${f1(x + r * 0.5)} ${f1(y - r * 0.4)}`, 'none', C.white, r * 0.24));
const noC = (x: number, y: number, r = 7) => all(circle(x, y, r, RED, C.ink, 1.2), line(`M${f1(x - r * 0.4)} ${f1(y - r * 0.4)} L${f1(x + r * 0.4)} ${f1(y + r * 0.4)} M${f1(x + r * 0.4)} ${f1(y - r * 0.4)} L${f1(x - r * 0.4)} ${f1(y + r * 0.4)}`, C.white, r * 0.24));
const trash = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-8 -6 L8 -6 L6 12 L-6 12 Z', C.grey, C.ink, 1.4), rect(-10, -10, 20, 4, C.grey, 1, C.ink, 1.2), rect(-3, -13, 6, 3, C.grey, 1, C.ink, 1), line('M-3 -2 L-2.4 9 M0 -2 L0 9 M3 -2 L2.4 9', C.ink, 1));
const play = (x: number, y: number, r = 8, col: string = GOOD) => all(circle(x, y, r, col, C.ink, 1.2), path(`M${f1(x - r * 0.3)} ${f1(y - r * 0.45)} L${f1(x + r * 0.5)} ${y} L${f1(x - r * 0.3)} ${f1(y + r * 0.45)} Z`, C.white, null));
const recDot = (x: number, y: number, r = 7) => all(circle(x, y, r + 2.4, C.white, C.ink, 1.2), circle(x, y, r, RED, null));
/** The usual voicemail icon: two reels joined by a line. */
const vmail = (x: number, y: number, s = 1, col: string = C.ink) => g(`translate(${x} ${y}) scale(${s})`, circle(-6, 0, 4, 'none', col, 2), circle(6, 0, 4, 'none', col, 2), line('M-6 4 L6 4', col, 2));
/** Waveform bars. */
const wave = (x: number, y: number, w: number, col: string = C.white, sw = 1.4, seed = 0) => all(...Array.from({ length: Math.floor(w / 3.2) }, (_, i) => { const h = 2 + (((i + seed) * 7) % 5) * 1.6; return line(`M${f1(x + i * 3.2)} ${f1(y - h)} L${f1(x + i * 3.2)} ${f1(y + h)}`, col, sw); }));
const clock = (x: number, y: number, r = 8, hm: [number, number] = [-90, 0], fill: string = C.white) => all(circle(x, y, r, fill, C.ink, 1.4), ...[0, 90, 180, 270].map((a) => circle(f1(x + Math.cos((a * Math.PI) / 180) * r * 0.75), f1(y + Math.sin((a * Math.PI) / 180) * r * 0.75), 0.7, C.ink, null)),
  line(`M${x} ${y} L${f1(x + Math.cos((hm[0] * Math.PI) / 180) * r * 0.5)} ${f1(y + Math.sin((hm[0] * Math.PI) / 180) * r * 0.5)}`, C.ink, 1.6), line(`M${x} ${y} L${f1(x + Math.cos((hm[1] * Math.PI) / 180) * r * 0.75)} ${f1(y + Math.sin((hm[1] * Math.PI) / 180) * r * 0.75)}`, C.ink, 1.2));
const hourglass = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-8, -12, 16, 3, C.brown, 1, C.ink, 1), rect(-8, 9, 16, 3, C.brown, 1, C.ink, 1), path('M-6 -9 L6 -9 L1 0 L6 9 L-6 9 L-1 0 Z', 'rgba(220,240,252,0.8)', C.ink, 1.2), path('M-4 -7 L4 -7 L0.6 -1 Z M-4 9 L4 9 L0 5 Z', C.gold, null));
/** Chat bubble (rounded rectangle) with grey text lines; right = own message. */
const cb = (x: number, y: number, w: number, h = 10, right = false, n = 1, col?: string) => all(rect(f1(x - w / 2), f1(y - h / 2), w, h, col ?? (right ? ME : YOU), 4, C.ink, 0.8), ...Array.from({ length: n }, (_, i) => line(`M${f1(x - w / 2 + 3)} ${f1(y - h / 2 + 4 + i * 3.4)} L${f1(x + w / 2 - 3 - (i % 2) * 4)} ${f1(y - h / 2 + 4 + i * 3.4)}`, right ? BLUE : '#7a8590', 1)));
/** Round avatar with head and shoulders. */
const av = (x: number, y: number, r: number, col: string, hair: string = C.hair, long = false) => all(circle(x, y, r, '#f0f3f6', C.ink, 1), long ? path(`M${f1(x - r * 0.42)} ${f1(y - r * 0.1)} C${f1(x - r * 0.5)} ${f1(y + r * 0.35)} ${f1(x + r * 0.5)} ${f1(y + r * 0.35)} ${f1(x + r * 0.42)} ${f1(y - r * 0.1)} Z`, hair, null) : '', path(`M${f1(x - r * 0.62)} ${f1(y + r * 0.82)} C${f1(x - r * 0.62)} ${f1(y + r * 0.3)} ${f1(x + r * 0.62)} ${f1(y + r * 0.3)} ${f1(x + r * 0.62)} ${f1(y + r * 0.82)} Z`, col, null), circle(x, f1(y - r * 0.2), f1(r * 0.34), C.skin, null), path(`M${f1(x - r * 0.34)} ${f1(y - r * 0.24)} C${f1(x - r * 0.34)} ${f1(y - r * 0.66)} ${f1(x + r * 0.34)} ${f1(y - r * 0.66)} ${f1(x + r * 0.34)} ${f1(y - r * 0.24)} Z`, hair, null));
/** Emoji face. */
const emo = (x: number, y: number, r: number, kind: 'smile' | 'laugh' | 'wink' | 'sad' | 'angry' | 'love' | 'shock' | 'flat' = 'smile') => {
  const k = r / 10, ink = C.ink;
  const eyes = kind === 'laugh' ? path(`M${f1(x - 6 * k)} ${f1(y - 2 * k)} Q${f1(x - 4 * k)} ${f1(y - 5 * k)} ${f1(x - 2 * k)} ${f1(y - 2 * k)} M${f1(x + 2 * k)} ${f1(y - 2 * k)} Q${f1(x + 4 * k)} ${f1(y - 5 * k)} ${f1(x + 6 * k)} ${f1(y - 2 * k)}`, 'none', ink, 1.4 * k)
    : kind === 'wink' ? all(circle(f1(x - 4 * k), f1(y - 3 * k), f1(1.4 * k), ink, null), line(`M${f1(x + 2 * k)} ${f1(y - 3 * k)} L${f1(x + 6 * k)} ${f1(y - 3 * k)}`, ink, 1.4 * k))
    : kind === 'love' ? all(heart(f1(x - 4 * k), f1(y - 3 * k), f1(0.3 * k)), heart(f1(x + 4 * k), f1(y - 3 * k), f1(0.3 * k)))
    : kind === 'shock' ? all(circle(f1(x - 4 * k), f1(y - 3 * k), f1(2 * k), C.white, ink, 0.8), circle(f1(x + 4 * k), f1(y - 3 * k), f1(2 * k), C.white, ink, 0.8), circle(f1(x - 4 * k), f1(y - 3 * k), f1(0.9 * k), ink, null), circle(f1(x + 4 * k), f1(y - 3 * k), f1(0.9 * k), ink, null))
    : all(circle(f1(x - 4 * k), f1(y - 3 * k), f1(1.4 * k), ink, null), circle(f1(x + 4 * k), f1(y - 3 * k), f1(1.4 * k), ink, null));
  const brows = kind === 'angry' ? line(`M${f1(x - 7 * k)} ${f1(y - 7 * k)} L${f1(x - 2 * k)} ${f1(y - 5 * k)} M${f1(x + 7 * k)} ${f1(y - 7 * k)} L${f1(x + 2 * k)} ${f1(y - 5 * k)}`, ink, 1.3 * k) : '';
  const mouth = kind === 'laugh' ? path(`M${f1(x - 6 * k)} ${f1(y + 2 * k)} Q${x} ${f1(y + 10 * k)} ${f1(x + 6 * k)} ${f1(y + 2 * k)} Z`, '#c84a4a', ink, 1 * k)
    : kind === 'sad' || kind === 'angry' ? path(`M${f1(x - 4 * k)} ${f1(y + 5 * k)} Q${x} ${f1(y + 1.6 * k)} ${f1(x + 4 * k)} ${f1(y + 5 * k)}`, 'none', ink, 1.4 * k)
    : kind === 'shock' ? ellipse(x, f1(y + 4 * k), f1(2 * k), f1(2.6 * k), '#c84a4a', ink, 0.8)
    : kind === 'flat' ? line(`M${f1(x - 4 * k)} ${f1(y + 4 * k)} L${f1(x + 4 * k)} ${f1(y + 4 * k)}`, ink, 1.4 * k)
    : path(`M${f1(x - 5 * k)} ${f1(y + 2 * k)} Q${x} ${f1(y + 7 * k)} ${f1(x + 5 * k)} ${f1(y + 2 * k)}`, 'none', ink, 1.4 * k);
  return all(circle(x, y, r, kind === 'angry' ? '#f0905a' : C.yellow, C.ink, 1.2), eyes, brows, mouth);
};
const thumb = (x: number, y: number, s = 1, down = false, col: string = C.skin) => g(`translate(${x} ${y}) scale(${s}${down ? ' -1' : ''})`, path('M-6 -1 L-2 -1 L1 -9 C2 -12 6 -11 5 -7 L4 -2 L9 -2 C12 -2 12 2 10 3 C12 4 11 7 9 7 C10 9 8 11 6 10 L-2 10 L-6 9 Z', col, C.ink, 1.2), rect(-10, -2, 5, 13, BLUE, 1, C.ink, 1.2));
/** Keypad 3×4 with optional highlighted key index. */
const keypad = (x: number, y: number, s = 1, hi = -1) => g(`translate(${x} ${y}) scale(${s})`, ...Array.from({ length: 12 }, (_, i) => { const kx = -16 + (i % 3) * 16, ky = -24 + Math.floor(i / 3) * 16; const lab = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '*', '0', '#'][i]!; return all(circle(kx, ky, 6.4, i === hi ? '#f6e08a' : '#5a5d68', i === hi ? HL : C.ink, i === hi ? 1.8 : 1), T(kx, ky + 3, lab, 7.4, i === hi ? C.ink : C.white)); }));
/** Pointing finger (index finger up, tip at x, y). */
const finger = (x: number, y: number, s = 1, rot = 0) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, path('M-2.6 0 C-2.6 -3 2.6 -3 2.6 0 L2.6 10 L8 10 C12 10 12 14 12 18 L10 26 L-2 26 L-4 14 C-6 12 -5 9 -2.6 10 Z', C.skin, C.ink, 1.3));
const table = (y = 86, x1 = 8, x2 = 112) => all(rect(x1, y, x2 - x1, 6, C.tan, 2, C.ink, 1.8), line(`M${x1 + 8} ${y + 6} L${x1 + 8} 112 M${x2 - 8} ${y + 6} L${x2 - 8} 112`, C.brown, 3));
const qm = (x: number, y: number, s = 13, col: string = C.navy) => T(x, f1(y + s * 0.36), '?', s, col);
const exm = (x: number, y: number, s = 13, col: string = HL) => T(x, f1(y + s * 0.36), '!', s, col);
const sweat = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M0 -5 C-3.4 0 -3 4 0 4 C3 4 3.4 0 0 -5 Z', '#9ad0f0', C.ink, 0.8));
const moon = (x: number, y: number, r = 8) => path(`M${x} ${y - r} A${r} ${r} 0 1 0 ${x + r} ${f1(y + r * 0.2)} A${f1(r * 0.75)} ${f1(r * 0.75)} 0 0 1 ${x} ${y - r} Z`, '#f6e08a', C.ink, 1.2);
const lines = (x: number, y: number, w: number, n: number, gap = 5, col: string = C.grey, sw = 1.2) => all(...Array.from({ length: n }, (_, i) => line(`M${x} ${y + i * gap} L${x + w - (i % 3) * 4} ${y + i * gap}`, col, sw)));

/** Clip any drawing to a window (nested svg, no ids needed). */
const clip = (x: number, y: number, w: number, h: number, ...k: Svg[]) => `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${x} ${y} ${w} ${h}" overflow="hidden">${k.join('')}</svg>`;
/** A video tile with a person (head and shoulders) in a rectangle. */
const tile = (x: number, y: number, w: number, h: number, col: string, bg = '#d8eef8', long = false, extra: Svg = '') => all(rect(f1(x - w / 2), f1(y - h / 2), w, h, bg, 1.4, C.ink, 0.8), clip(f1(x - w / 2), f1(y - h / 2), w, h, path(`M${f1(x - h * 0.42)} ${f1(y + h / 2)} C${f1(x - h * 0.42)} ${f1(y + h * 0.08)} ${f1(x + h * 0.42)} ${f1(y + h * 0.08)} ${f1(x + h * 0.42)} ${f1(y + h / 2)} Z`, col, C.ink, 0.6)), long ? path(`M${f1(x - h * 0.24)} ${f1(y - h * 0.06)} C${f1(x - h * 0.3)} ${f1(y + h * 0.2)} ${f1(x + h * 0.3)} ${f1(y + h * 0.2)} ${f1(x + h * 0.24)} ${f1(y - h * 0.06)} Z`, C.hair, null) : '', circle(x, f1(y - h * 0.08), f1(h * 0.2), C.skin, C.ink, 0.6), path(`M${f1(x - h * 0.2)} ${f1(y - h * 0.1)} C${f1(x - h * 0.2)} ${f1(y - h * 0.38)} ${f1(x + h * 0.2)} ${f1(y - h * 0.38)} ${f1(x + h * 0.2)} ${f1(y - h * 0.1)} Z`, C.hair, null), circle(f1(x - h * 0.07), f1(y - h * 0.08), f1(h * 0.025 + 0.2), C.ink, null), circle(f1(x + h * 0.07), f1(y - h * 0.08), f1(h * 0.025 + 0.2), C.ink, null), extra);
const chart = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-12, -9, 24, 18, C.white, 1, C.ink, 0.8), rect(-8, 0, 4, 6, BLUE, 0, null), rect(-2, -4, 4, 10, GOOD, 0, null), rect(4, -6, 4, 12, HL, 0, null));
const earIcon = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-5 -2 C-5 -10 7 -10 7 -2 C7 3 2 4 2 8 C2 11 -2 11 -3 9', C.skin, C.ink, 1.4), path('M-1 -2 C-1 -5 3 -5 3 -2', 'none', C.ink, 1));

const PIX = ['..hhhh..', '.hhhhhh.', 'hhssssh.', 'hseseshh', 'hssssssh', '.sspps..', '.ccsscc.', 'cccccccc', 'cccccccc', 'cccccccc'];
const PIXC: Record<string, string> = { h: C.hair, s: C.skin, e: C.ink, p: '#c84a4a', c: C.orange };
const sun = (x: number, y: number, r = 5) => circle(x, y, r, C.yellow, C.ink, 1);

/** Phone keyboard rows (local phone units, bottom part of the screen). */
const kb = (y: number, hi: number[] = [], hiCol: string = HL) => all(rect(-11.4, y - 1, 22.8, 18 - y + 1, '#d0d6dc', 0, null), ...[0, 1, 2].flatMap((r) => Array.from({ length: r === 2 ? 7 : r === 1 ? 9 : 10 }, (_, i) => { const n = r === 2 ? 7 : r === 1 ? 9 : 10, w = 2, gap = 0.26, x0 = -(n * (w + gap)) / 2 + i * (w + gap); const idx = r * 10 + i; return rect(f1(x0), f1(y + r * 3.4), w, 2.8, hi.includes(idx) ? hiCol : C.white, 0.4, null); })), rect(-6, f1(y + 10.4), 12, 2.6, C.white, 0.4, null));
